// «Запомнить меня» off: the session also needs a browser-session cookie, which the browser drops on close.
const ALIVE='officesklad-alive';
function signedIn(users){const s=store.get('session');return s&&s.expires>Date.now()&&users[s.email]&&(!s.tab||document.cookie.split('; ').includes(ALIVE+'=1'))?s.email:null;}
function stateOf(users,email){
  const u=users[email];if(!u)return blankState();
  const date=t=>new Date(t).toLocaleDateString('ru-RU',{day:'2-digit',month:'2-digit',year:'numeric'});
  const orders=(store.get('orders')||[]).filter(o=>o.email===email).sort((a,b)=>b.id-a.id)
    .map(o=>({id:String(o.id+40000),total:o.cents/100,items:o.items,details:o.details,date:date(o.created),sample:!!o.sample}));
  return {...u.state,user:u.name,email,orders};
}
// A guest's cart lives in this browser until sign-in; then it joins the account's cart (quantities add up).
const guestState=()=>({...blankState(),cart:store.get('guestCart')||{}});
function cleanCart(cart){
  const clean={};
  if(!cart||typeof cart!=='object'||Array.isArray(cart)||Object.keys(cart).length>P.length)fail('Некорректная корзина.');
  for(const [id,q] of Object.entries(cart)){if(!(typeof id==='string'&&product(id))||!Number.isInteger(q)||q<1||q>9999)fail('Некорректное количество товара.');clean[id]=q;}
  return clean;
}
// Test data: two past orders for a new account, so that «Повторить заказ» has something to repeat.
const SAMPLE_ORDERS=[{days:41,items:{'2':50,'3':50,'4':100,'1':24}},{days:12,items:{'36':10,'65':20,'81':10,'141':10}}];
function seedOrders(email){
  const orders=store.get('orders')||[];let seq=store.get('seq')||0;
  for(const o of SAMPLE_ORDERS){
    const items=Object.fromEntries(Object.entries(o.items).filter(([id])=>product(id)));
    const cents=Object.entries(items).reduce((s,[id,q])=>s+Math.round(product(id).price*100)*q,0);
    orders.push({id:++seq,email,cents,items,details:{},created:Date.now()-o.days*86400e3,sample:true});
  }
  store.set('orders',orders);store.set('seq',seq);
}
const ORDER_FIELDS=[['name','Ф.И.О.',1],['email','E-Mail',1],['phone','Телефон',1],['zip','Индекс',1],['location','Местоположение',1],['city','Город',0],['address','Адрес доставки',1]];
function orderDetails(body){
  const text=(key,label,limit,multiline)=>{
    let value=body[key]??'';if(typeof value!=='string')fail('Некорректное значение поля «'+label+'».');
    value=value.trim();if(value.length>limit)fail('Поле «'+label+'» не должно быть длиннее '+limit+' символов.');
    if(/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/.test(value)||(!multiline&&/[\r\n]/.test(value)))fail('Поле «'+label+'» содержит недопустимые символы.');
    return value;
  };
  const d={};for(const [key,label] of ORDER_FIELDS)d[key]=text(key,label,200);
  const missing=ORDER_FIELDS.filter(([key,,req])=>req&&!d[key]).map(f=>f[1]);
  if(missing.length)fail('Не заполнены обязательные поля: '+missing.join(', ')+'.');
  if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(d.email))fail('Введите корректный E-Mail.');
  if(d.phone.replace(/\D/g,'').length<5)fail('Введите корректный телефон.');
  d.payer=text('payer','Тип плательщика',200);if(d.payer!==PAYER)fail('Выберите тип плательщика.');
  d.delivery=text('delivery','Доставка',200);if(d.delivery!==FREE_DELIVERY)fail('Выберите способ доставки.');
  d.payment=PAYMENT;d.comment=text('comment','Комментарий к заказу',1000,true);
  return d;
}
async function local(path,method,body){
  const users=store.get('users')||{},me=signedIn(users);
  if(method==='GET'&&path==='/state')return me?stateOf(users,me):guestState();
  if((path==='/register'||path==='/login')&&method==='POST'){
    const email=String(body.email||'').trim().toLowerCase(),password=body.password;
    if(typeof password!=='string'||password.length<8||password.length>128)fail('Пароль должен содержать от 8 до 128 символов.');
    if(email.length>254||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))fail('Введите корректный email.');
    if(path==='/register'){
      const name=String(body.name||'').trim().slice(0,100);if(!name)fail('Укажите имя.');
      if(users[email])fail('Этот email уже зарегистрирован. Войдите в аккаунт.');
      const salt=hex(crypto.getRandomValues(new Uint8Array(16)));
      users[email]={name,salt,password:await digest(password,salt),state:{cart:{},favorites:[],compare:[],city:''},created:Date.now()};
      store.set('users',users);
    }else if(!users[email]||await digest(password,users[email].salt)!==users[email].password)fail('Неверный email или пароль.');
    const u=users[email],guest=store.get('guestCart')||{},cart=u.state.cart||(u.state.cart={});
    for(const [id,q] of Object.entries(guest))if(product(id))cart[id]=Math.min(9999,(cart[id]||0)+q);
    if(!u.sampled){seedOrders(email);u.sampled=true;}
    store.set('users',users);store.drop('guestCart');
    const remember=body.remember!==false;
    store.set('session',{email,expires:Date.now()+(remember?30*86400e3:86400e3),tab:!remember});
    if(!remember)document.cookie=ALIVE+'=1; path='+B+'; SameSite=Lax';
    return stateOf(users,email);
  }
  if(path==='/logout'&&method==='POST'){store.drop('session');return guestState();}
  if(!me&&path==='/state'&&method==='PUT'){store.set('guestCart',cleanCart(body.cart||{}));return guestState();}
  if(!me)fail('Войдите в аккаунт.');
  if(path==='/state'&&method==='PUT'){
    const known=id=>typeof id==='string'&&!!product(id);
    const data={cart:cleanCart(body.cart||{}),city:String(body.city??'').slice(0,100)};
    for(const field of ['favorites','compare']){
      const items=body[field]||[];
      if(!Array.isArray(items)||items.length>P.length||!items.every(known))fail('Некорректный список товаров.');
      data[field]=[...new Set(items)];
    }
    users[me].state=data;store.set('users',users);
    return stateOf(users,me);
  }
  if(path==='/orders'&&method==='POST'){
    // As on the server: the total is counted here from the catalogue prices, the cart is emptied by the same step.
    const details=orderDetails(body),cart=users[me].state.cart||{};
    const sum=Object.entries(cart).reduce((s,[id,q])=>s+Math.round((product(id)?.price||0)*100)*q,0);
    if(sum<500000)fail('Минимальная сумма заказа — 5 000 руб.');
    const orders=store.get('orders')||[],id=(store.get('seq')||0)+1;
    orders.push({id,email:me,cents:sum,items:cart,details,created:Date.now()});
    users[me].state.cart={};
    store.set('seq',id);store.set('orders',orders);store.set('users',users);
    return {state:stateOf(users,me),orderId:String(id+40000)};
  }
  fail('Метод не поддерживается');
}
async function api(path,method='GET',body){
  if(STATIC)return local(path,method,body);
  const response=await fetch(B+'api'+path,{method,credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,cache:'no-store'});
  const data=await response.json();if(!response.ok)throw new Error(data.error||'Не удалось выполнить запрос.');return data;
}
async function save(){
  saving=true;
  try {state=await api('/state','PUT',{cart:state.cart,favorites:state.favorites,compare:state.compare,city:state.city||''});header();}
  finally {saving=false;}
}
function failure(error){modal('<p>'+esc(error.message||'Не удалось связаться с сервером. Попробуйте ещё раз.')+'</p>');}
// Sums are counted in kopecks (as the server does), so that 0.1+0.2-type drift never reaches the screen.
const cents=()=>Object.entries(state.cart).reduce((s,[id,q])=>s+Math.round((product(id)?.price||0)*100)*q,0);
const total=()=>cents()/100;
const count=()=>Object.values(state.cart).reduce((a,b)=>a+b,0);
const grp=n=>(Math.round(n*100)/100).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g,' ');   // 5332 -> "5 332.00", as on the original cart
const rub=n=>grp(n)+' руб.';
// own=true: the body brings its own close button (cart window); locked=true: the guest window, deliberately not closable.
function modal(body,locked=false,own=false){
  $('#demo-dialog')?.remove();
  const el=document.createElement('div');el.id='demo-dialog';el.dataset.locked=String(locked);el.innerHTML='<div class="demo-shade"></div><section class="demo-modal'+(own?' demo-cartmodal':'')+'" role="dialog" aria-modal="true" tabindex="-1">'+(locked||own?'':'<button class="demo-close" aria-label="Закрыть">×</button>')+body+'</section>';
  document.body.append(el);el.querySelector('.demo-close,.demo-modal').focus();
  el.addEventListener('click',e=>{if(!locked&&e.target.closest('.demo-shade,.demo-close'))el.remove();});
}
const money2=n=>(Math.round(n*100)/100).toFixed(2)+' руб.';
const unit=p=>p.unit||'шт.';
const ICON={
  scales:'<svg viewBox="0 0 24 24" width="26" height="26" aria-hidden="true"><path fill="currentColor" d="M12 3a1 1 0 0 1 1 1v1h6a1 1 0 1 1 0 2h-.4l2.4 6.4a1 1 0 0 1-.3 1.1A4.4 4.4 0 0 1 18 15a4.4 4.4 0 0 1-2.7-.9 1 1 0 0 1-.3-1.1L17.4 7H13v11h3a1 1 0 1 1 0 2H8a1 1 0 1 1 0-2h3V7H6.6L9 13a1 1 0 0 1-.3 1.1A4.4 4.4 0 0 1 6 15a4.4 4.4 0 0 1-2.7-.9 1 1 0 0 1-.3-1.1L5.4 7H5a1 1 0 0 1 0-2h6V4a1 1 0 0 1 1-1zM6 12.5l-1.3-3.3L3.5 12.5zm12 0l-1.3-3.3-1.2 3.3z"/></svg>',
  heart:'<svg viewBox="0 0 24 24" width="26" height="26" aria-hidden="true"><path fill="currentColor" d="M12 21s-8-4.9-9.7-10C1.2 7.6 3.2 4.5 6.3 4.5c2.2 0 4 1.3 5.7 3.2 1.7-1.9 3.5-3.2 5.7-3.2 3.1 0 5.1 3.1 4 6.5C20 16.1 12 21 12 21z"/></svg>',
  check:'<svg viewBox="0 0 24 24" width="28" height="28" aria-hidden="true"><path fill="none" stroke="currentColor" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round" d="M4.5 12.8l5 5L19.8 6.5"/></svg>',
  bag:'<svg viewBox="0 0 24 24" width="26" height="26" aria-hidden="true"><path fill="none" stroke="currentColor" stroke-width="1.9" stroke-linejoin="round" d="M5 8h14l1 13H4zM8.5 8V6.5a3.5 3.5 0 0 1 7 0V8"/></svg>',
  back:'<svg viewBox="0 0 24 24" width="24" height="24" aria-hidden="true"><path fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" d="M20 12a8 8 0 1 1-2.5-5.8M20 4v5h-5"/></svg>'
};
// "Товар добавлен в корзину" for a signed-in user, modelled on the original window.
function cartModal(id){
  const p=product(id);
  modal('<header class="dcm-head"><h3 id="dcm-title">Товар добавлен в корзину</h3><button class="demo-close" aria-label="Закрыть"><svg viewBox="0 0 24 24" width="30" height="30" aria-hidden="true"><path d="M3 3l18 18M21 3L3 21" stroke="currentColor" stroke-width="1.6" fill="none"/></svg></button></header>'
   +'<div class="dcm-body" data-id="'+id+'"><div class="dcm-pic"><img src="'+p.image+'" alt="'+esc(p.name)+'"></div><div class="dcm-info"><div class="dcm-name">'+esc(p.name)+'</div><div class="dcm-price">'+money2(p.price)+' / '+esc(unit(p))+'</div>'
   +'<div class="dcm-qty"><span>Кол-во:</span><button type="button" data-cm="minus" aria-label="Уменьшить количество">−</button><input id="dcm-qty" type="text" inputmode="numeric" aria-label="Количество" value="1"><button type="button" data-cm="plus" aria-label="Увеличить количество">+</button></div>'
   +'<div class="dcm-total">Итого: <b id="dcm-total"></b></div><p id="dcm-error" role="alert"></p></div></div>'
   +'<footer class="dcm-foot"><button type="button" class="dcm-ico" data-cm="compare" title="Сравнить" aria-label="Сравнить">'+ICON.scales+'</button><button type="button" class="dcm-ico" data-cm="favorite" title="В избранное" aria-label="В избранное">'+ICON.heart+'</button><span class="dcm-ico dcm-check" title="Товар в корзине">'+ICON.check+'</span>'
   +'<button type="button" class="dcm-act dcm-remove" data-cm="remove">Удалить из корзины</button><button type="button" class="dcm-act dcm-continue" data-cm="continue"><i>'+ICON.back+'</i>Продолжить покупки</button><a class="dcm-act dcm-go" href="'+B+'personal/cart/"><i>'+ICON.bag+'</i>Перейти в корзину</a></footer>',false,true);
  $('#demo-dialog').querySelector('.dcm-body').closest('.demo-modal').setAttribute('aria-labelledby','dcm-title');
  cartModalSync(id);
}
function cartModalSync(id){
  const p=product(id),q=state.cart[id]||1,box=$('#demo-dialog .dcm-body');if(!p||!box||box.dataset.id!==String(id))return;
  $('#dcm-qty').value=q;$('#dcm-total').textContent=money2(p.price*q);
  $('[data-cm=compare]').classList.toggle('on',state.compare.includes(String(id)));
  $('[data-cm=favorite]').classList.toggle('on',state.favorites.includes(String(id)));
}
// Clicks are queued, not dropped: "+ + +" in quick succession gives +3, each step saved on the server.
let cmQueue=Promise.resolve();
function cartModalAction(a){
  const act=a.dataset.cm;
  if(act==='continue'){$('#demo-dialog')?.remove();return;}
  cmQueue=cmQueue.then(()=>cartModalRun(act));
}
async function cartModalRun(act){
  const box=$('#demo-dialog .dcm-body'),id=box?.dataset.id;if(!id||!ready)return;
  const err=$('#dcm-error');err.textContent='';
  const before=JSON.stringify([state.cart,state.favorites,state.compare]);
  try{
    if(act==='minus'||act==='plus'||act==='set'){
      const q=act==='set'?parseInt($('#dcm-qty').value):(state.cart[id]||1)+(act==='plus'?1:-1);
      state.cart[id]=Math.min(9999,Math.max(1,q||1));
    }else if(act==='remove'){delete state.cart[id];}
    else if(!state.user){authModal(act==='compare'?'Сравнение — для зарегистрированных':'Избранное — для зарегистрированных','Войдите, чтобы сохранить товар: корзина при этом сохранится.');return;}
    else{const type=act==='compare'?'compare':'favorites',i=state[type].indexOf(id);if(i<0)state[type].push(id);else state[type].splice(i,1);}
    await save();
    if(act==='remove'){$('#demo-dialog')?.remove();return;}
  }catch(error){
    [state.cart,state.favorites,state.compare]=JSON.parse(before);
    if($('#dcm-error'))$('#dcm-error').textContent=error.message||'Не удалось выполнить запрос.';
  }
  cartModalSync(id);
}
document.addEventListener('keydown',e=>{const dialog=$('#demo-dialog');if(e.key==='Escape'&&dialog?.dataset.locked!=='true')dialog?.remove();});
function header(){
  // Mini-cart as on the original: count badge, "В корзине <сумма>", "Оформить заказ" — the template's own markup is filled in.
  const cart=$('#flushTopCart');
  if(cart&&$('.cartTable',cart)){
    const to=(sel,fn)=>$$(sel,cart).forEach(fn),n=count();
    to('.count',x=>{x.textContent=n;});
    to('.cartLabel',x=>{x.textContent='В корзине';});
    to('.total',x=>{x.textContent=n?rub(total()):'пока пусто';});
    to('a',x=>{x.href=B+'personal/cart/';});
  }else if(cart)cart.innerHTML='<a href="'+B+'personal/cart/" class="demo-header-cart"><span class="demo-cart-symbol">🛒</span><span>В корзине <b>'+count()+'</b> '+(count()?'товаров<br>'+rub(total()):'пока пусто')+'</span></a><a href="'+B+'personal/cart/" class="demo-cart-checkout">Оформить заказ</a>';
  const foot=$('#flushFooterCart');if(foot)foot.innerHTML='<a href="'+B+'personal/cart/">КОРЗИНА&nbsp; '+count()+'</a>';
  if(state.user){
    $$('a[href*="/auth/"]').forEach(a=>{
      if(/вход/i.test(a.textContent)){a.textContent='Личный кабинет';a.href=B+'personal/order/';}
      else if(/регистрац/i.test(a.textContent)){a.textContent='Выход';a.href='#logout';}
    });
  }
}
// Stock as a wholesale buyer needs it: how many, or when it is expected.
function stockLabel(p){return p.stock>0?'<span class="os-stock os-in">В наличии: '+p.stock.toLocaleString('ru-RU')+' '+esc(unit(p))+'</span>':'<span class="os-stock os-out">'+(p.expected?'Ожидается '+esc(p.expected):'Нет в наличии')+'</span>';}
const minPriceNote=()=>'Цена при заказе от '+Number(C.minPriceFrom).toLocaleString('ru-RU')+' ₽';
const minPriceTip=()=>'<button type="button" class="os-tip" aria-label="'+esc(minPriceNote())+'" data-tip="'+esc(minPriceNote())+'">?</button>';
// One card for tile and list view: the list is the same markup laid out in a row (demo.css, body.os-view-list).
function card(p){return '<article class="demo-card" data-product="'+p.id+'"><a class="demo-card-pic" href="'+p.path+'"><img src="'+p.image+'" alt="'+esc(p.name)+'" loading="lazy"></a>'
  +'<div class="demo-card-info"><a class="demo-card-name" href="'+p.path+'">'+esc(p.name)+'</a><small class="demo-sku">Код: '+esc(p.code||'')+(p.sku?' · Арт.: '+esc(p.sku):'')+'</small>'+stockLabel(p)+'</div>'
  +'<div class="demo-card-price"><div class="demo-price">'+money(p.price)+' / '+esc(unit(p))+'</div><small class="demo-min">Мин. цена '+money(p.price*.89)+' '+minPriceTip()+'</small></div>'
  +'<div class="demo-card-buy"><input class="quantity" type="text" inputmode="numeric" maxlength="4" value="1" aria-label="Количество: '+esc(p.name)+'"><button class="demo-button" data-add="'+p.id+'">В корзину</button></div>'
  +'<div class="demo-card-extra"><button data-favorite="'+p.id+'">♡ Избранное</button><button data-compare="'+p.id+'">⇄ Сравнение</button></div></article>';}
// ---- Sign-in from the place the buyer stopped at: backurl brings them back.
const here=()=>location.pathname+location.search;
function authUrl(extra){return B+'auth/?'+(extra?extra+'&':'')+'backurl='+encodeURIComponent(here());}
// Only a path of this site is followed: no scheme, no //host. Old-style paths ("/catalog/…") are read from the site root.
function backUrl(){
  const u=new URLSearchParams(location.search).get('backurl')||'';
  if(!/^\/(?!\/)[^\\:]*$/.test(u)||u.startsWith(B+'auth/'))return B;
  return u.startsWith(B)?u:B+u.slice(1);
}
// Sign-in offered where an account is needed (favourites, comparison, placing the order); the cart itself needs none.
function authModal(title,text){
  modal('<h3 id="demo-auth-title">'+esc(title)+'</h3><p>'+esc(text)+'</p><div class="demo-dialog-actions"><a class="demo-button" href="'+authUrl()+'">Войти</a><a class="demo-button demo-button-light" href="'+authUrl('register=yes')+'">Зарегистрироваться</a></div>');
  $('#demo-dialog .demo-modal').setAttribute('aria-labelledby','demo-auth-title');
}
// ---- Dead ends (empty cart, nothing found): a person to talk to.
function managerBlock(){
  return '<div class="demo-manager"><h3>Не нашли? Позвоните или оставьте список менеджеру</h3><p>Подберём товары по кодам, названиям из прайса или фото и соберём заказ за вас.</p>'
   +'<div class="demo-manager-actions"><a class="demo-manager-phone" href="'+esc(C.phoneHref)+'">'+esc(C.phone)+'</a><button type="button" class="demo-button" data-callback>Заказать звонок</button></div>'
   +'<p class="demo-muted">'+esc(C.hours)+' · <a href="mailto:'+esc(C.email)+'">'+esc(C.email)+'</a></p></div>';
}
function callbackModal(){
  modal('<h3 id="demo-callback-title">Заказать звонок</h3><form id="demo-callback" novalidate><p>Оставьте телефон — менеджер перезвонит в рабочее время ('+esc(C.hours)+').</p>'
   +'<label>Ваше имя<input name="name" autocomplete="name" maxlength="100"></label><label>Телефон *<input name="phone" type="tel" autocomplete="tel" inputmode="tel" maxlength="30" required></label>'
   +'<label>Список товаров или вопрос<textarea name="comment" rows="4" maxlength="2000" placeholder="Коды или названия и количество"></textarea></label>'
   +'<label class="demo-consent"><input type="checkbox" name="agree"> Я согласен на обработку персональных данных</label><p id="demo-callback-error" role="alert"></p><button class="demo-button" type="submit">Жду звонка</button></form>');
  $('#demo-dialog .demo-modal').setAttribute('aria-labelledby','demo-callback-title');
}
function sendCallback(f){
  const err=$('#demo-callback-error'),phone=f.elements.phone.value.trim();
  if(phone.replace(/\D/g,'').length<10){err.textContent='Введите телефон: не меньше 10 цифр.';f.elements.phone.focus();return;}
  if(!f.elements.agree.checked){err.textContent='Нужно согласие на обработку персональных данных.';return;}
  try{const list=store.get('callbacks')||[];list.push({name:f.elements.name.value.trim().slice(0,100),phone,comment:f.elements.comment.value.trim().slice(0,2000),at:Date.now(),page:here()});store.set('callbacks',list.slice(-50));}
  catch(error){err.textContent=error.message;return;}
  modal('<h3>Заявка принята</h3><p>Менеджер перезвонит на номер '+esc(phone)+' в рабочее время ('+esc(C.hours)+').</p><p class="demo-muted">Демо-магазин: заявка сохраняется только в этом браузере и не передаётся поставщику.</p>');
}
async function add(id,q=1){
  if(!ready||saving)return;
  if(!product(id))return;
  state.cart[id]=Math.min(9999,(state.cart[id]||0)+q);try{await save();}catch(error){failure(error);return;}
  cartModal(id);
}
// ---- Cart page: notice, actions, table, order form on the same page (the original has no separate checkout page).
